window.SE_NOI=[{"id":"s1","n":"Chặng 1","t":"Khởi động","lv":"Pre-A1","goal":"Từ con số 0: mở miệng nói được những câu sống còn đầu tiên.","lessons":[{"id":"s1l1","t":"Bảng chữ cái & đánh vần tên","vi":"Alphabet and spelling","goal":"Đọc đúng 26 chữ cái và đánh vần được tên mình.","ph":[["How do you spell your name?","Tên bạn đánh vần thế nào?"],["My name is M-I-N-H.","Tên tôi là M-I-N-H."],["Can you spell that, please?","Bạn đánh vần giúp tôi được không?"],["Is that A or E?","Là chữ A hay chữ E?"],["Yes, that's right.","Vâng, đúng rồi."],["Sorry, it's with two L's.","Xin lỗi, có hai chữ L."]],"dl":[["A","How do you spell your name?","Tên bạn đánh vần thế nào?"],["B","M-I-N-H. Minh.","M-I-N-H. Minh."],["A","Is that M as in Mike?","M như trong Mike phải không?"],["B","Yes, that's right.","Vâng, đúng rồi."]],"tip":"Đọc từng chữ chậm và tách rõ. Các chữ dễ lẫn: E /iː/ và A /eɪ/, G /dʒiː/ và J /dʒeɪ/, I /aɪ/ và Y /waɪ/. Nếu ngập ngừng, dùng \"as in\" để chỉ từ gợi ý (M as in Mike).","ai":{"role":"A friendly receptionist at a language school who is registering a new student. Ask the student's first name and family name and ask them to spell both letters one by one. Then confirm by repeating the spelling.","open":"Hello, welcome! I'm going to register you. What's your first name?","targets":["How do you spell","It's","Sorry, could you repeat"],"goal":"Đánh vần tên của bạn cho lễ tân ghi sổ."}},{"id":"s1l2","t":"Chào hỏi","vi":"Greetings","goal":"Chào và hỏi thăm theo buổi trong ngày.","ph":[["Hello! / Hi!","Xin chào! / Chào!"],["Good morning.","Chào buổi sáng."],["How are you?","Bạn khỏe không?"],["I'm fine, thank you. And you?","Tôi khỏe, cảm ơn. Còn bạn?"],["Nice to meet you.","Rất vui được gặp bạn."],["See you later. / Goodbye.","Hẹn gặp lại. / Tạm biệt."]],"dl":[["A","Good morning! How are you?","Chào buổi sáng! Bạn khỏe không?"],["B","I'm fine, thank you. And you?","Tôi khỏe, cảm ơn. Còn bạn?"],["A","Very well, thanks.","Rất khỏe, cảm ơn."],["B","See you later!","Hẹn gặp lại!"]],"tip":"\"How are you?\" thường chỉ là lời chào xã giao, người ta trả lời ngắn \"Fine, thanks. And you?\". Đừng kể lể dài. Nhớ đáp lại bằng \"And you?\" để cuộc nói chuyện có đi có lại.","ai":{"role":"A neighbour you meet in the morning in the lift. Greet them, ask how they are, answer their questions, then say goodbye. Use very simple English, one short sentence at a time.","open":"Good morning! How are you today?","targets":["Good morning","I'm fine","And you","See you"],"goal":"Chào hỏi người hàng xóm trong thang máy."}},{"id":"s1l3","t":"Giới thiệu bản thân","vi":"Introducing yourself","goal":"Nói tên, quê quán và nghề nghiệp bằng câu ngắn.","ph":[["My name is Linh.","Tên tôi là Linh."],["I'm from Vietnam.","Tôi đến từ Việt Nam."],["I live in Hanoi.","Tôi sống ở Hà Nội."],["I'm a student. / I'm a teacher.","Tôi là học sinh. / Tôi là giáo viên."],["What about you?","Còn bạn thì sao?"],["Where are you from?","Bạn đến từ đâu?"]],"dl":[["A","Hi, I'm Tom. Where are you from?","Chào, tôi là Tom. Bạn đến từ đâu?"],["B","I'm from Vietnam. I live in Hanoi.","Tôi đến từ Việt Nam. Tôi sống ở Hà Nội."],["A","What do you do?","Bạn làm nghề gì?"],["B","I'm a student. What about you?","Tôi là sinh viên. Còn bạn thì sao?"]],"tip":"Công thức dễ nhất: I'm + tên/nghề, I'm from + nơi, I live in + thành phố. Học thuộc 3 mẫu này là giới thiệu được ngay. \"What do you do?\" hỏi nghề nghiệp, không hỏi bạn đang làm gì lúc này.","ai":{"role":"A friendly student called Tom meeting the learner at an English club for the first time. Ask name, where they are from, where they live and what they do. React warmly and share one fact about yourself.","open":"Hi! I'm Tom. Nice to meet you. What's your name?","targets":["My name is","I'm from","I live in","I'm a"],"goal":"Tự giới thiệu với một người bạn mới ở câu lạc bộ tiếng Anh."}},{"id":"s1l4","t":"Con số, tuổi và số điện thoại","vi":"Numbers, age and phone numbers","goal":"Nói số từ 0 đến 100, tuổi và đọc số điện thoại.","ph":[["I'm twenty-five years old.","Tôi 25 tuổi."],["My phone number is zero nine one two...","Số điện thoại của tôi là 0912..."],["How old are you?","Bạn bao nhiêu tuổi?"],["It costs fifteen dollars.","Cái này giá 15 đô la."],["Thirteen or thirty?","13 hay 30?"],["Could you say it again, please?","Bạn nói lại giúp tôi được không?"]],"dl":[["A","What's your phone number?","Số điện thoại của bạn là gì?"],["B","It's zero nine one two, three four five, six seven eight.","Là 0912 345 678."],["A","Zero nine one two, three four five, six seven eight?","0912 345 678 phải không?"],["B","Yes, that's right.","Vâng, đúng rồi."]],"tip":"Cẩn thận cặp -teen / -ty: thirteen /ˌθɜːˈtiːn/ nhấn âm cuối, thirty /ˈθɜːti/ nhấn âm đầu. Đọc số điện thoại từng chữ số, nhóm 3–4 số và nghỉ giữa các nhóm. \"0\" đọc là zero hoặc oh.","ai":{"role":"A shop assistant who needs to take the learner's age and phone number for a membership card. Ask how old they are and for their phone number, then read the number back slowly to check.","open":"Hello! To make your membership card, I need some information. How old are you?","targets":["years old","phone number","Could you repeat","That's right"],"goal":"Cho cô nhân viên tuổi và số điện thoại của bạn."}},{"id":"s1l5","t":"Cảm ơn, xin lỗi, xin phép","vi":"Thanks, sorry and excuse me","goal":"Dùng 5 cụm lịch sự để không bao giờ bị coi là thô lỗ.","ph":[["Thank you very much.","Cảm ơn bạn rất nhiều."],["You're welcome.","Không có gì."],["I'm sorry.","Tôi xin lỗi."],["Excuse me, can I sit here?","Xin lỗi, tôi ngồi đây được không?"],["No problem. / That's OK.","Không sao đâu."],["Please. / Here you are.","Làm ơn. / Của bạn đây."]],"dl":[["A","Excuse me, is this seat free?","Xin lỗi, chỗ này còn trống không?"],["B","Yes, please sit down.","Vâng, mời bạn ngồi."],["A","Thank you very much.","Cảm ơn bạn rất nhiều."],["B","You're welcome.","Không có gì."]],"tip":"Người Anh nói \"please\", \"thank you\", \"sorry\" rất thường xuyên, gần như mỗi câu. \"Excuse me\" dùng để xin phép/gây chú ý trước; \"Sorry\" dùng sau khi lỡ làm phiền.","ai":{"role":"A stranger on a crowded bus. You (the AI) accidentally bump into the learner and apologise, then ask if the seat next to them is free. Keep it very short and polite, and let the learner use thanks and apologies.","open":"Oh, sorry! I didn't see you. Are you OK?","targets":["Sorry","Excuse me","Thank you","No problem"],"goal":"Xử lý một va chạm nhỏ trên xe buýt bằng các cụm lịch sự."}},{"id":"s1l6","t":"Khi không hiểu","vi":"When you don't understand","goal":"Học cách xin nhắc lại và nhờ nói chậm thay vì im lặng.","ph":[["Sorry, could you repeat that?","Xin lỗi, bạn nhắc lại được không?"],["Could you speak more slowly, please?","Bạn nói chậm hơn được không?"],["I don't understand.","Tôi không hiểu."],["What does \"receipt\" mean?","\"Receipt\" nghĩa là gì?"],["How do you say this in English?","Cái này nói tiếng Anh thế nào?"],["Can you write it down?","Bạn viết ra giúp tôi được không?"]],"dl":[["A","The meeting is at half past nine.","Cuộc họp lúc chín rưỡi."],["B","Sorry, could you speak more slowly?","Xin lỗi, bạn nói chậm hơn được không?"],["A","The meeting is at nine thirty.","Cuộc họp lúc 9 giờ 30."],["B","Oh, nine thirty. Thank you!","À, 9 giờ 30. Cảm ơn bạn!"]],"tip":"Đây là bài quan trọng nhất của chặng 1: người nói giỏi cũng cần xin nhắc lại. Đừng gật đầu giả vờ hiểu. Nói rõ \"Sorry?\" với giọng đi lên cũng được.","ai":{"role":"A fast-talking tour guide giving the learner directions to the museum using slightly too difficult words. The learner should ask you to repeat, to slow down and what a word means. When they do, rephrase in simpler words.","open":"So, the museum is opposite the pharmacy, just past the roundabout. You can't miss it!","targets":["Could you repeat","more slowly","What does","mean"],"goal":"Hỏi lại khi người hướng dẫn nói nhanh và khó hiểu."}},{"id":"s1l7","t":"Xin giúp đỡ trong lớp & nơi công cộng","vi":"Asking for help","goal":"Nhờ giúp đỡ và hỏi vật dụng đơn giản.","ph":[["Can you help me, please?","Bạn giúp tôi được không?"],["Where is the toilet?","Nhà vệ sinh ở đâu?"],["Do you have a pen?","Bạn có bút không?"],["I need a glass of water.","Tôi cần một cốc nước."],["Could I use your phone?","Tôi dùng điện thoại của bạn được không?"],["Is there a bank near here?","Gần đây có ngân hàng không?"]],"dl":[["A","Can you help me, please?","Bạn giúp tôi được không?"],["B","Of course. What do you need?","Tất nhiên. Bạn cần gì?"],["A","Where is the toilet?","Nhà vệ sinh ở đâu?"],["B","It's over there, next to the stairs.","Ở đằng kia, cạnh cầu thang."]],"tip":"\"Can you...?\" và \"Could you...?\" đều để nhờ; Could lịch sự hơn. Câu hỏi có/không lên giọng cuối câu. Thêm \"please\" ở cuối là đủ lịch sự cho người mới.","ai":{"role":"A helpful staff member at a language-school front desk. The learner arrives needing help (a pen, water, the toilet, a phone). Answer their requests simply and ask whether they need anything else.","open":"Hello, can I help you?","targets":["Can you help","Where is","Do you have","Thank you"],"goal":"Nhờ nhân viên quầy lễ tân giúp bạn vài việc nhỏ."}}]},{"id":"s2","n":"Chặng 2","t":"Giao tiếp cơ bản","lv":"A1","goal":"Nói về cuộc sống hằng ngày bằng câu đơn giản và hỏi lại được.","lessons":[{"id":"s2l1","t":"Gia đình & bạn bè","vi":"Family and friends","goal":"Nói về người thân: ai, bao nhiêu tuổi, làm gì.","ph":[["I have two brothers and one sister.","Tôi có hai anh em trai và một chị gái."],["My mother is a nurse.","Mẹ tôi là y tá."],["He is tall and funny.","Anh ấy cao và hài hước."],["We live together in a small house.","Chúng tôi sống cùng nhau trong một ngôi nhà nhỏ."],["Do you have any children?","Bạn có con không?"],["Is your family big or small?","Gia đình bạn đông hay ít người?"]],"dl":[["A","Tell me about your family.","Hãy kể cho tôi về gia đình bạn."],["B","I have a mother, a father and a little sister.","Tôi có mẹ, bố và một em gái."],["A","How old is your sister?","Em gái bạn bao nhiêu tuổi?"],["B","She is twelve. She likes drawing.","Em ấy 12 tuổi. Em thích vẽ."]],"tip":"Chú ý \"has\" với he/she/it: My sister has a bike. Số nhiều của \"brother\" là \"brothers\", còn \"child\" thành \"children\". \"Do you have...?\" hỏi sở hữu.","ai":{"role":"A new colleague at lunch who is curious about the learner's family. Ask who is in the family, their ages and jobs, using simple present questions. Share one short fact about your own family each time.","open":"So, tell me about your family. Is it big or small?","targets":["I have","My mother","He/She is","years old"],"goal":"Kể về những người trong gia đình bạn."}},{"id":"s2l2","t":"Công việc & học tập","vi":"Work and study","goal":"Nói bạn làm gì, ở đâu, thích hay không.","ph":[["I work in a bank.","Tôi làm việc ở ngân hàng."],["I study English at university.","Tôi học tiếng Anh ở đại học."],["I start work at eight o'clock.","Tôi bắt đầu làm việc lúc 8 giờ."],["My job is interesting but busy.","Công việc của tôi thú vị nhưng bận."],["What do you do?","Bạn làm nghề gì?"],["Do you like your job?","Bạn có thích công việc của mình không?"]],"dl":[["A","What do you do?","Bạn làm nghề gì?"],["B","I work in a bank. I'm an accountant.","Tôi làm ở ngân hàng. Tôi là kế toán."],["A","Do you like your job?","Bạn có thích công việc của mình không?"],["B","Yes, it's interesting, but it's very busy.","Có, nó thú vị nhưng rất bận."]],"tip":"Giới từ: work IN a bank/company, work FOR a company, study AT university. \"I'm an accountant\" (a/an trước nghề). Dùng \"but\" để thêm một ý trái ngược, câu sẽ tự nhiên hơn.","ai":{"role":"A person at an English-club social evening who asks about the learner's job or studies. Ask what they do, where, what they like, and what time they start. Keep questions short.","open":"Hi again! So, what do you do? Do you work or study?","targets":["I work","I study","I start","I like"],"goal":"Nói về việc làm hoặc việc học của bạn."}},{"id":"s2l3","t":"Thói quen mỗi ngày","vi":"Daily routine","goal":"Nói một ngày của bạn bằng thì hiện tại đơn.","ph":[["I get up at six thirty.","Tôi dậy lúc 6 giờ 30."],["I have breakfast at home.","Tôi ăn sáng ở nhà."],["I go to work by bus.","Tôi đi làm bằng xe buýt."],["I usually finish at five.","Tôi thường tan làm lúc 5 giờ."],["In the evening I cook dinner.","Buổi tối tôi nấu bữa tối."],["I never go to bed late.","Tôi không bao giờ đi ngủ muộn."]],"dl":[["A","What time do you get up?","Bạn dậy lúc mấy giờ?"],["B","I get up at six thirty.","Tôi dậy lúc 6 giờ 30."],["A","And how do you go to work?","Rồi bạn đi làm bằng gì?"],["B","I go by bus. It takes thirty minutes.","Tôi đi xe buýt. Mất 30 phút."]],"tip":"Trạng từ tần suất đứng trước động từ thường: always, usually, often, sometimes, never. He/she/it thêm -s: she gets up. Dùng \"at\" cho giờ, \"in the morning/evening\" cho buổi.","ai":{"role":"A curious flatmate who wants to know the learner's typical weekday. Ask about wake-up time, breakfast, travel, work and evening. Use simple present questions and comment briefly on the answers.","open":"I'm curious about your day. What time do you usually get up?","targets":["I get up","I usually","I go to","in the evening"],"goal":"Mô tả một ngày bình thường của bạn."}},{"id":"s2l4","t":"Gọi món ăn & đồ uống","vi":"Ordering food and drink","goal":"Gọi món, hỏi giá, thanh toán ở nhà hàng.","ph":[["Can I have the menu, please?","Cho tôi xem thực đơn được không?"],["I'd like a chicken salad.","Tôi muốn một đĩa salad gà."],["Could I have some water?","Cho tôi ít nước được không?"],["What do you recommend?","Bạn gợi ý món nào?"],["Can we have the bill, please?","Cho chúng tôi xin hóa đơn."],["Is service included?","Đã gồm phí phục vụ chưa?"]],"dl":[["A","Are you ready to order?","Bạn đã sẵn sàng gọi món chưa?"],["B","Yes. I'd like the chicken salad, please.","Rồi. Cho tôi món salad gà."],["A","Anything to drink?","Bạn dùng đồ uống gì không?"],["B","A glass of orange juice, please.","Cho tôi một ly nước cam."]],"tip":"\"I'd like\" (I would like) lịch sự hơn \"I want\". \"Can I have...?\" thân thiện, dùng hằng ngày. Đếm được: a salad / two salads; không đếm được: some water, some rice.","ai":{"role":"A waiter in a small restaurant. Greet the customer, offer the menu, take their order for a main dish and a drink, ask about allergies or extras, and finally bring the bill. Keep a polite, natural tone with short sentences.","open":"Good evening! Welcome. Here's the menu. Are you ready to order?","targets":["I'd like","Can I have","What do you recommend","the bill"],"goal":"Gọi một bữa ăn đầy đủ và thanh toán."}},{"id":"s2l5","t":"Mua sắm & hỏi giá","vi":"Shopping","goal":"Hỏi giá, size, màu và trả giá lịch sự.","ph":[["How much is this?","Cái này giá bao nhiêu?"],["Do you have this in a larger size?","Bạn có cỡ lớn hơn không?"],["Can I try it on?","Tôi thử được không?"],["It's too expensive.","Nó đắt quá."],["I'll take it.","Tôi lấy cái này."],["Do you accept cards?","Bạn có nhận thẻ không?"]],"dl":[["A","Can I help you?","Tôi giúp gì được cho bạn?"],["B","Yes, how much is this T-shirt?","Vâng, áo phông này giá bao nhiêu?"],["A","It's twenty dollars.","20 đô la."],["B","Do you have it in blue? I'll take it.","Bạn có màu xanh không? Tôi lấy cái này."]],"tip":"\"This/that\" cho số ít, \"these/those\" cho số nhiều. \"Too + tính từ\" nghĩa là quá (too expensive). \"How much\" hỏi giá hoặc lượng không đếm được; \"How many\" hỏi số lượng đếm được.","ai":{"role":"A shop assistant in a clothes shop. Help the learner choose a T-shirt: ask the size and colour they want, quote prices in dollars, let them try it on, and take payment. Stay polite and use short sentences.","open":"Hello! Can I help you find something today?","targets":["How much","Do you have","Can I try","I'll take"],"goal":"Mua một chiếc áo ở cửa hàng."}},{"id":"s2l6","t":"Hỏi đường","vi":"Asking for directions","goal":"Hỏi và hiểu chỉ đường cơ bản.","ph":[["Excuse me, where is the station?","Xin lỗi, ga ở đâu?"],["Turn left at the traffic lights.","Rẽ trái ở đèn giao thông."],["Go straight on for two minutes.","Đi thẳng hai phút."],["It's next to the bank.","Nó ở cạnh ngân hàng."],["Is it far from here?","Nó có xa đây không?"],["How can I get to the airport?","Tôi đến sân bay bằng cách nào?"]],"dl":[["A","Excuse me, how can I get to the park?","Xin lỗi, tôi đến công viên bằng cách nào?"],["B","Go straight on, then turn right at the bank.","Đi thẳng rồi rẽ phải ở ngân hàng."],["A","Is it far?","Có xa không?"],["B","No, it's about five minutes on foot.","Không, đi bộ khoảng 5 phút."]],"tip":"Từ chỉ đường: straight on, turn left/right, at the corner, opposite, next to, behind, between. Lặp lại để kiểm tra: \"So, straight on and then right?\" — một thói quen rất tốt.","ai":{"role":"A local person on the street. The learner will ask for directions to a place (station, park, supermarket). Give clear short directions with landmarks, and check that the learner understood by asking them to repeat the route.","open":"Hi there! You look lost. Can I help you?","targets":["where is","turn left","Is it far","Thank you"],"goal":"Hỏi đường đến ga tàu và nhắc lại để chắc chắn."}},{"id":"s2l7","t":"Thời gian & hẹn gặp","vi":"Time and making plans","goal":"Nói giờ, ngày và hẹn gặp bạn bè.","ph":[["What time is it?","Mấy giờ rồi?"],["It's half past three.","Ba giờ rưỡi."],["Are you free on Saturday?","Thứ Bảy bạn rảnh không?"],["Let's meet at seven o'clock.","Hẹn nhau lúc 7 giờ."],["Where shall we meet?","Chúng ta gặp ở đâu?"],["Sorry, I can't make it.","Xin lỗi, tôi không đến được."]],"dl":[["A","Are you free on Saturday?","Thứ Bảy bạn rảnh không?"],["B","Yes. What shall we do?","Có. Chúng ta làm gì đây?"],["A","Let's see a film at seven o'clock.","Đi xem phim lúc 7 giờ nhé."],["B","Great idea! See you at the cinema.","Ý hay đấy! Gặp ở rạp nhé."]],"tip":"Giờ: past (sau) cho 1–30 phút, to (kém) cho 31–59; quarter past / quarter to. Mời: \"Let's...\" / \"Would you like to...?\". Từ chối lịch sự: \"Sorry, I can't, but how about Sunday?\".","ai":{"role":"A friend who wants to arrange a weekend meeting. Suggest an activity, a day and a time, ask where to meet, and agree on a final plan. If the learner says they can't, ask for another time.","open":"Hey! Are you free this weekend? Let's do something!","targets":["Are you free","Let's","What time","Where shall we"],"goal":"Hẹn bạn một buổi cuối tuần: ngày, giờ, địa điểm."}},{"id":"s2l8","t":"Sở thích","vi":"Hobbies and free time","goal":"Nói bạn thích gì, làm gì lúc rảnh, tần suất.","ph":[["I like playing football.","Tôi thích chơi bóng đá."],["I love listening to music.","Tôi rất thích nghe nhạc."],["In my free time I read books.","Lúc rảnh tôi đọc sách."],["I'm not very good at drawing.","Tôi không giỏi vẽ lắm."],["How often do you go swimming?","Bạn bơi bao lâu một lần?"],["Twice a week.","Hai lần một tuần."]],"dl":[["A","What do you do in your free time?","Bạn làm gì lúc rảnh?"],["B","I like playing football and watching films.","Tôi thích chơi bóng đá và xem phim."],["A","How often do you play?","Bạn chơi bao lâu một lần?"],["B","Twice a week, at the weekend.","Hai lần một tuần, vào cuối tuần."]],"tip":"Sau like/love/enjoy/hate dùng V-ing: I like playing. \"Be good at + V-ing / danh từ\". Tần suất: once, twice, three times a week; every day; sometimes.","ai":{"role":"A new friend chatting about free time. Ask about hobbies, how often, who with, and whether the learner would like to try something new together. Use simple present and 'like + -ing' questions.","open":"So, what do you like doing in your free time?","targets":["I like","I love","How often","I'm good at"],"goal":"Nói chuyện với bạn mới về sở thích."}}]},{"id":"s3","n":"Chặng 3","t":"Tình huống đời sống","lv":"A2","goal":"Xử lý các tình huống thường gặp: kể chuyện đã qua, lên kế hoạch, đi lại, khám bệnh.","lessons":[{"id":"s3l1","t":"Kể chuyện hôm qua","vi":"Talking about yesterday","goal":"Dùng thì quá khứ đơn để kể điều đã xảy ra.","ph":[["Yesterday I went to the market.","Hôm qua tôi đi chợ."],["I met an old friend there.","Tôi gặp một người bạn cũ ở đó."],["We had lunch together.","Chúng tôi ăn trưa cùng nhau."],["I didn't do anything special.","Tôi không làm gì đặc biệt."],["What did you do last weekend?","Cuối tuần trước bạn làm gì?"],["It was a really good day.","Đó là một ngày rất tuyệt."]],"dl":[["A","What did you do yesterday?","Hôm qua bạn làm gì?"],["B","I went to the cinema with my sister.","Tôi đi xem phim với chị gái."],["A","Did you like the film?","Bạn có thích phim không?"],["B","Yes, it was funny, but a bit long.","Có, nó hài hước nhưng hơi dài."]],"tip":"Động từ có quy tắc thêm -ed (walked); bất quy tắc phải học thuộc: go–went, have–had, see–saw, eat–ate, meet–met. Câu hỏi và phủ định dùng did/didn't + động từ nguyên mẫu: Did you go? I didn't go.","ai":{"role":"A friendly colleague on Monday morning who asks about the learner's weekend. Ask what they did, who with, where, and how it was. Show interest with follow-up questions about the details, and use simple past naturally.","open":"Hi! Good to see you. How was your weekend? What did you do?","targets":["I went","We had","It was","I didn't"],"goal":"Kể về cuối tuần vừa rồi của bạn."}},{"id":"s3l2","t":"Kế hoạch tương lai","vi":"Plans and intentions","goal":"Nói bạn sẽ làm gì với going to và will.","ph":[["I'm going to visit my grandparents.","Tôi sẽ đi thăm ông bà."],["We're going to leave at nine.","Chúng tôi sẽ khởi hành lúc 9 giờ."],["I'm meeting a friend tomorrow.","Ngày mai tôi gặp một người bạn."],["I think it will rain tonight.","Tôi nghĩ tối nay trời sẽ mưa."],["What are you doing this weekend?","Cuối tuần này bạn làm gì?"],["I haven't decided yet.","Tôi chưa quyết định."]],"dl":[["A","What are you going to do this summer?","Hè này bạn định làm gì?"],["B","I'm going to travel to Da Nang with my family.","Tôi sẽ đi Đà Nẵng với gia đình."],["A","That sounds great! How long are you staying?","Nghe tuyệt đấy! Bạn ở lại bao lâu?"],["B","Five days. We're going to swim every morning.","Năm ngày. Chúng tôi sẽ bơi mỗi sáng."]],"tip":"Going to cho kế hoạch đã có sẵn; will cho dự đoán hoặc quyết định ngay lúc nói (I'll help you). Hiện tại tiếp diễn cũng dùng cho lịch hẹn chắc chắn: I'm meeting Tom at six.","ai":{"role":"A friend asking what the learner plans to do on the next holiday. Ask where, with whom, for how long, and what activities. Encourage the learner to use 'going to' and 'will' and give gentle suggestions.","open":"Your holiday is coming soon! What are you going to do?","targets":["I'm going to","We will","I think","How long"],"goal":"Nói về kế hoạch kỳ nghỉ sắp tới."}},{"id":"s3l3","t":"Khách sạn & du lịch","vi":"Travel and hotels","goal":"Đặt phòng, nhận phòng và hỏi dịch vụ.","ph":[["I have a reservation under Nguyen.","Tôi đã đặt phòng dưới tên Nguyễn."],["I'd like a double room for two nights.","Tôi muốn một phòng đôi cho hai đêm."],["Is breakfast included?","Có gồm bữa sáng không?"],["What time is check-out?","Mấy giờ trả phòng?"],["The air conditioner doesn't work.","Máy lạnh không hoạt động."],["Could you call a taxi for me?","Bạn gọi giúp tôi một chiếc taxi được không?"]],"dl":[["A","Good evening. Do you have a reservation?","Chào buổi tối. Bạn có đặt phòng chưa?"],["B","Yes, under Nguyen. A double room for two nights.","Có, tên Nguyễn. Một phòng đôi hai đêm."],["A","Here is your key. Breakfast is from seven to ten.","Chìa khóa của bạn đây. Bữa sáng từ 7 đến 10 giờ."],["B","Thank you. What time is check-out?","Cảm ơn. Mấy giờ trả phòng?"]],"tip":"Dùng \"Could you...?\" khi nhờ nhân viên. Khi có sự cố, nêu vấn đề trước, nhờ giải quyết sau: \"The shower is cold. Could someone have a look?\".","ai":{"role":"A hotel receptionist. Check the learner in (reservation, nights, room type), explain breakfast and check-out times, then handle a small problem the learner raises (for example the wifi or air conditioning). Be polite and helpful.","open":"Good afternoon, welcome to the Sunrise Hotel. How can I help you?","targets":["I have a reservation","Is breakfast included","What time","Could you"],"goal":"Nhận phòng khách sạn và báo một sự cố nhỏ."}},{"id":"s3l4","t":"Đi khám & sức khỏe","vi":"At the doctor","goal":"Mô tả triệu chứng và hiểu lời dặn của bác sĩ.","ph":[["I don't feel well.","Tôi thấy không khỏe."],["I have a headache and a sore throat.","Tôi bị đau đầu và đau họng."],["It started two days ago.","Nó bắt đầu từ hai ngày trước."],["Do I need to take any medicine?","Tôi có cần uống thuốc không?"],["You should rest and drink plenty of water.","Bạn nên nghỉ ngơi và uống nhiều nước."],["Take this twice a day after meals.","Uống thuốc này hai lần một ngày sau bữa ăn."]],"dl":[["A","What seems to be the problem?","Bạn bị làm sao?"],["B","I have a bad cough and a fever.","Tôi ho nhiều và bị sốt."],["A","How long have you felt like this?","Bạn bị như vậy bao lâu rồi?"],["B","About three days. Do I need medicine?","Khoảng ba ngày. Tôi có cần thuốc không?"]],"tip":"Bị đau chỗ nào: I have a + headache / stomachache / toothache; My + bộ phận + hurts. \"Should\" dùng để khuyên: You should rest. \"How long\" hỏi thời gian kéo dài.","ai":{"role":"A doctor in a small clinic. Ask what is wrong, how long, other symptoms, and then give simple advice with 'should'. Check that the learner understands how to take the medicine.","open":"Hello, please sit down. What seems to be the problem?","targets":["I have a","It started","Do I need","How often"],"goal":"Khám bệnh: nói triệu chứng và hiểu lời dặn."}},{"id":"s3l5","t":"Gọi điện thoại","vi":"On the phone","goal":"Mở đầu cuộc gọi, để lại lời nhắn, hẹn lịch.","ph":[["Hello, this is Linh speaking.","A lô, Linh đây ạ."],["Could I speak to Mr Brown, please?","Cho tôi nói chuyện với ông Brown được không?"],["I'm afraid he's not in at the moment.","Rất tiếc, hiện ông ấy không có ở đây."],["Can I take a message?","Tôi ghi lại lời nhắn được không?"],["Could you ask him to call me back?","Bạn nhắn ông ấy gọi lại cho tôi được không?"],["Sorry, the line is bad.","Xin lỗi, đường truyền kém."]],"dl":[["A","Hello, Sunshine Dental. How can I help you?","A lô, nha khoa Sunshine nghe đây. Tôi giúp gì được ạ?"],["B","Hello, I'd like to make an appointment.","A lô, tôi muốn đặt lịch hẹn."],["A","Certainly. Is Tuesday at ten OK?","Được ạ. Thứ Ba lúc 10 giờ được không?"],["B","Yes, that's fine. Thank you.","Được, ổn ạ. Cảm ơn bạn."]],"tip":"Điện thoại không có hình, nên hãy phát âm rõ và nói chậm hơn thường lệ. Xác nhận lại thông tin quan trọng (ngày, giờ, tên) bằng cách lặp lại. \"This is...\" dùng để xưng tên trên điện thoại, không dùng \"I am\".","ai":{"role":"A receptionist at a dental clinic answering the phone. The learner wants to book an appointment. Ask for their name, the preferred day and time, and a phone number, then confirm everything by repeating it.","open":"Good morning, Sunshine Dental Clinic. How can I help you?","targets":["I'd like to make","Is ... OK","Could you repeat","Thank you"],"goal":"Gọi đặt lịch hẹn nha sĩ."}},{"id":"s3l6","t":"Mô tả người & so sánh","vi":"Describing and comparing","goal":"Tả ngoại hình, tính cách và so sánh hai thứ.","ph":[["She is tall with long black hair.","Cô ấy cao, tóc đen dài."],["He's friendly and very generous.","Anh ấy thân thiện và rất hào phóng."],["This phone is cheaper than that one.","Điện thoại này rẻ hơn cái kia."],["It's the best restaurant in town.","Đó là nhà hàng tốt nhất trong thành phố."],["Which one do you prefer?","Bạn thích cái nào hơn?"],["They look the same, but they're different.","Trông giống nhau nhưng thật ra khác nhau."]],"dl":[["A","What does your brother look like?","Anh trai bạn trông thế nào?"],["B","He's tall and thin, with short brown hair.","Anh ấy cao, gầy, tóc nâu ngắn."],["A","Is he older than you?","Anh ấy lớn tuổi hơn bạn à?"],["B","Yes, he's three years older, and much funnier!","Vâng, hơn ba tuổi và vui tính hơn nhiều!"]],"tip":"So sánh hơn: tính từ ngắn + -er (taller), tính từ dài dùng more (more expensive). Hơn nhất: the tallest, the most expensive. Bất quy tắc: good–better–best, bad–worse–worst. \"Look like\" hỏi hình dáng; \"be like\" hỏi tính cách.","ai":{"role":"A friend trying to recognise someone at the airport. Ask the learner to describe a person they are meeting (height, hair, clothes, age) and then compare two options they are choosing between, like two hotels or two phones.","open":"I'm going to meet your cousin at the airport! What does he look like?","targets":["He is","She has","is taller than","the best"],"goal":"Tả một người bạn sẽ đón và so sánh hai lựa chọn."}},{"id":"s3l7","t":"Kể về một chuyến đi","vi":"Talking about a trip","goal":"Kể trình tự chuyến đi bằng quá khứ và từ nối đơn giản.","ph":[["Last summer I went to Hue.","Hè năm ngoái tôi đã đi Huế."],["First, we visited the old city.","Đầu tiên, chúng tôi thăm cố đô."],["Then we took a boat on the river.","Sau đó chúng tôi đi thuyền trên sông."],["After that, we ate local food.","Sau đó, chúng tôi ăn đồ ăn địa phương."],["The weather was great.","Thời tiết rất đẹp."],["I'd love to go back one day.","Tôi muốn quay lại vào một ngày nào đó."]],"dl":[["A","Where did you go on holiday?","Bạn đi nghỉ ở đâu?"],["B","We went to Hue. The old city was beautiful.","Chúng tôi đi Huế. Cố đô rất đẹp."],["A","What did you eat there?","Bạn đã ăn gì ở đó?"],["B","We tried bun bo Hue. It was delicious!","Chúng tôi thử bún bò Huế. Ngon lắm!"]],"tip":"Từ nối trình tự: first, then, after that, finally. Thêm cảm xúc bằng tính từ (amazing, delicious, crowded) để lời kể sống động hơn. Giữ thì quá khứ xuyên suốt đoạn kể.","ai":{"role":"A curious friend who loves travel stories. Ask the learner to tell you about their last trip: where, when, with whom, what they did and ate, and what they liked best. Ask one follow-up question at a time.","open":"You just came back from a trip, right? Tell me everything!","targets":["First","Then","After that","It was"],"goal":"Kể một chuyến đi theo trình tự."}}]},{"id":"s4","n":"Chặng 4","t":"Diễn đạt ý kiến","lv":"B1","goal":"Nói có lý lẽ: nêu quan điểm, đồng ý/phản đối, kể chuyện, giải thích.","lessons":[{"id":"s4l1","t":"Nêu ý kiến","vi":"Giving opinions","goal":"Nói quan điểm và đưa lý do bằng các khung câu.","ph":[["In my opinion, it's a good idea.","Theo tôi, đó là một ý hay."],["I think that learning English is useful.","Tôi nghĩ học tiếng Anh rất hữu ích."],["The main reason is that it's cheaper.","Lý do chính là nó rẻ hơn."],["For example, you can talk to people.","Ví dụ, bạn có thể nói chuyện với mọi người."],["As far as I'm concerned, it depends.","Theo tôi thì còn tùy."],["That's why I prefer working from home.","Đó là lý do tôi thích làm việc ở nhà."]],"dl":[["A","Do you think students should wear uniforms?","Bạn có nghĩ học sinh nên mặc đồng phục không?"],["B","In my opinion, yes. It's fairer for everyone.","Theo tôi là có. Như vậy công bằng hơn cho mọi người."],["A","Why do you think so?","Sao bạn nghĩ vậy?"],["B","Because nobody feels worse than others, and it saves time.","Vì không ai thấy mình kém hơn người khác, và nó tiết kiệm thời gian."]],"tip":"Công thức trả lời hay: Ý kiến (I think...) → Lý do (because/the main reason is...) → Ví dụ (for example...). Chỉ cần 3 câu như vậy là đủ cho một câu trả lời trọn vẹn.","ai":{"role":"A debate-club friend asking for opinions on everyday topics (uniforms, working from home, social media). Ask for the learner's opinion, ask 'why?', and ask for an example. Do not argue yet; just encourage them to build a full answer.","open":"Let's practise opinions. Do you think people should work from home?","targets":["In my opinion","The main reason","For example","That's why"],"goal":"Nêu ý kiến có lý do và ví dụ về làm việc tại nhà."}},{"id":"s4l2","t":"Đồng ý & không đồng ý","vi":"Agreeing and disagreeing","goal":"Đồng ý, phản đối lịch sự, và đặt điều kiện.","ph":[["I totally agree with you.","Tôi hoàn toàn đồng ý với bạn."],["That's a good point, but...","Ý đó hay, nhưng..."],["I see what you mean, however...","Tôi hiểu ý bạn, tuy nhiên..."],["I'm not sure I agree.","Tôi không chắc mình đồng ý."],["Maybe, but don't you think it's expensive?","Có thể, nhưng bạn không thấy nó đắt sao?"],["Let's agree to disagree.","Hãy cứ để mỗi người một ý."]],"dl":[["A","I think everyone should learn to cook.","Tôi nghĩ ai cũng nên học nấu ăn."],["B","That's a good point, but some people really don't have time.","Ý hay đấy, nhưng có người thật sự không có thời gian."],["A","True, but cooking can be quick and simple.","Đúng, nhưng nấu ăn có thể nhanh và đơn giản."],["B","I see what you mean. Maybe I should try.","Tôi hiểu ý bạn. Có lẽ tôi nên thử."]],"tip":"Người nói tiếng Anh hiếm khi nói thẳng \"You're wrong\". Hãy ghi nhận ý đối phương trước (\"That's a good point\"), rồi mới đưa ý khác (\"but/however\"). Thái độ mềm mà ý vẫn rõ ràng.","ai":{"role":"A friendly debate partner who sometimes disagrees politely with the learner on light topics (cooking, pets, city vs countryside). State an opinion, let the learner agree or disagree, and respond to their reasons naturally.","open":"I think living in a big city is better than living in the countryside. What do you think?","targets":["I agree","That's a good point, but","I'm not sure","However"],"goal":"Thảo luận có đồng ý/không đồng ý lịch sự."}},{"id":"s4l3","t":"Kể chuyện","vi":"Telling a story","goal":"Kể một sự việc có mở đầu, diễn biến, kết thúc.","ph":[["It happened last year.","Chuyện xảy ra năm ngoái."],["I was walking home when it started to rain.","Tôi đang đi bộ về nhà thì trời đổ mưa."],["Suddenly, I realised I had lost my keys.","Đột nhiên tôi nhận ra mình đã mất chìa khóa."],["In the end, a stranger helped me.","Cuối cùng, một người lạ đã giúp tôi."],["I felt so relieved.","Tôi thấy nhẹ cả người."],["The funny thing is that it was my neighbour.","Điều buồn cười là đó là hàng xóm của tôi."]],"dl":[["A","Have you ever had a bad day?","Bạn đã bao giờ có một ngày tồi tệ chưa?"],["B","Yes. Last month I missed my bus and was late for work.","Có. Tháng trước tôi lỡ xe buýt và đi làm muộn."],["A","Oh no! What happened next?","Ôi không! Rồi chuyện gì xảy ra?"],["B","My boss was nice, and in the end it was fine.","Sếp tôi dễ chịu, cuối cùng mọi chuyện ổn."]],"tip":"Quá khứ tiếp diễn (was/were + V-ing) cho nền cảnh, quá khứ đơn cho sự kiện chen vào: I was walking when it started to rain. Từ nối kể chuyện: one day, suddenly, meanwhile, in the end.","ai":{"role":"A friend who loves hearing funny or unlucky stories. Ask the learner to tell you about a day when something unexpected happened. Ask 'what happened next?' and show emotion, to help them keep the story going in a clear order.","open":"Tell me about a time when something unexpected happened to you!","targets":["I was walking when","Suddenly","In the end","I felt"],"goal":"Kể một câu chuyện bất ngờ của bạn."}},{"id":"s4l4","t":"Giải thích lý do & nguyên nhân","vi":"Explaining reasons and results","goal":"Dùng because, so, although để nối ý.","ph":[["I was late because the bus broke down.","Tôi đến muộn vì xe buýt bị hỏng."],["It was raining, so we stayed at home.","Trời mưa nên chúng tôi ở nhà."],["Although it was cheap, it wasn't good.","Dù rẻ nhưng nó không tốt."],["That's the reason why I changed my job.","Đó là lý do tôi đổi việc."],["As a result, I felt much better.","Kết quả là tôi thấy khá hơn nhiều."],["I did it in order to save money.","Tôi làm vậy để tiết kiệm tiền."]],"dl":[["A","Why did you move to a new city?","Sao bạn chuyển đến thành phố mới?"],["B","Because I got a better job there.","Vì tôi có công việc tốt hơn ở đó."],["A","Was it difficult?","Có khó không?"],["B","Although it was hard at first, I made friends quickly.","Dù lúc đầu khó, tôi nhanh chóng có bạn."]],"tip":"Because + mệnh đề (because it rained); because of + danh từ (because of the rain). So chỉ kết quả. Although/though chỉ sự đối lập và không đi cùng \"but\" trong cùng một câu.","ai":{"role":"A curious friend who asks 'why?' about the learner's choices (a job change, a purchase, a hobby, a trip). Ask for reasons and results one by one, and encourage them to use because, so and although.","open":"You changed something recently, didn't you? Why did you decide to do that?","targets":["because","so","although","as a result"],"goal":"Giải thích lý do cho một quyết định gần đây."}},{"id":"s4l5","t":"Phỏng vấn xin việc cơ bản","vi":"A basic job interview","goal":"Giới thiệu bản thân, điểm mạnh, kinh nghiệm.","ph":[["Thank you for inviting me today.","Cảm ơn vì đã mời tôi hôm nay."],["I have two years of experience in sales.","Tôi có hai năm kinh nghiệm bán hàng."],["My biggest strength is communication.","Điểm mạnh nhất của tôi là giao tiếp."],["I'm a quick learner and a good team player.","Tôi học nhanh và làm việc nhóm tốt."],["I'm applying because I want to grow.","Tôi ứng tuyển vì muốn phát triển."],["When could I expect to hear from you?","Khi nào tôi có thể nhận phản hồi?"]],"dl":[["A","Tell me about yourself.","Hãy giới thiệu về bản thân bạn."],["B","I'm a marketing assistant with two years of experience.","Tôi là trợ lý marketing với hai năm kinh nghiệm."],["A","What is your biggest strength?","Điểm mạnh lớn nhất của bạn là gì?"],["B","I'm organised, and I learn quickly.","Tôi làm việc có tổ chức và học nhanh."]],"tip":"Mỗi câu trả lời nên có một ví dụ cụ thể: \"I'm organised. For example, I managed three projects at once.\" Tránh trả lời một từ. Giữ tiếng nói chậm, rõ và nhìn thẳng người phỏng vấn.","ai":{"role":"A polite HR manager interviewing the learner for a junior customer-service job. Ask them to introduce themselves, about experience, strengths, why they want the job, and whether they have questions. Probe each answer with one follow-up question.","open":"Good morning! Thank you for coming. Please, take a seat. Could you tell me about yourself?","targets":["I have experience","My strength is","I'm applying because","Could you tell me"],"goal":"Trả lời một buổi phỏng vấn xin việc cơ bản."}},{"id":"s4l6","t":"Phàn nàn lịch sự & giải quyết vấn đề","vi":"Making a complaint","goal":"Nêu vấn đề rõ ràng và đề nghị cách giải quyết.","ph":[["I'm afraid there's a problem with my order.","Tôi e là có vấn đề với đơn hàng của tôi."],["It arrived damaged.","Hàng đến nơi bị hỏng."],["I'd like a refund, please.","Tôi muốn được hoàn tiền."],["Could you replace it for me?","Bạn đổi giúp tôi cái mới được không?"],["I've been waiting for forty minutes.","Tôi đã đợi bốn mươi phút rồi."],["I understand, but this is the second time.","Tôi hiểu, nhưng đây là lần thứ hai."]],"dl":[["A","Hello, how can I help you?","Xin chào, tôi giúp gì được bạn?"],["B","I'm afraid the jacket I bought is the wrong size.","Tôi e là chiếc áo khoác tôi mua sai cỡ."],["A","I'm sorry about that. Would you like a refund or an exchange?","Tôi xin lỗi. Bạn muốn hoàn tiền hay đổi?"],["B","An exchange, please. Do you have a larger one?","Cho tôi đổi. Bạn có cỡ lớn hơn không?"]],"tip":"Giữ giọng bình tĩnh, nêu sự việc (không trách người), rồi nói bạn muốn gì. Mở đầu mềm: \"I'm afraid...\" / \"Unfortunately...\". Đưa giải pháp: refund (hoàn tiền), exchange (đổi), replacement (hàng thay thế).","ai":{"role":"A customer-service agent in an online shop. The learner has a problem with an order (late, damaged, or wrong item). Ask for details, apologise, offer two options, and confirm the solution. Stay calm even if the learner is firm.","open":"Thank you for calling customer service. How can I help you today?","targets":["I'm afraid","I'd like a refund","Could you","I understand"],"goal":"Phàn nàn về một đơn hàng bị lỗi."}},{"id":"s4l7","t":"Kinh nghiệm & điều đã từng làm","vi":"Experiences","goal":"Dùng present perfect: ever, never, already, yet.","ph":[["Have you ever been to Japan?","Bạn đã từng đến Nhật chưa?"],["I've never tried sushi.","Tôi chưa bao giờ thử sushi."],["I've already finished my homework.","Tôi đã làm xong bài tập rồi."],["I haven't seen that film yet.","Tôi chưa xem bộ phim đó."],["I've lived here for five years.","Tôi đã sống ở đây năm năm."],["It was the best trip I've ever had.","Đó là chuyến đi tuyệt nhất tôi từng có."]],"dl":[["A","Have you ever tried skiing?","Bạn đã từng trượt tuyết chưa?"],["B","No, I've never tried it. Have you?","Chưa, tôi chưa từng thử. Còn bạn?"],["A","Yes, I went last winter. It was amazing.","Có, mùa đông trước tôi đi. Tuyệt lắm."],["B","I'd love to go one day.","Tôi muốn đi vào một ngày nào đó."]],"tip":"Present perfect (have/has + V3) nói về trải nghiệm không nêu thời điểm. Khi nêu mốc thời gian cụ thể (last year, in 2020) phải chuyển sang quá khứ đơn: I went last winter. \"For\" + khoảng thời gian, \"since\" + mốc.","ai":{"role":"A talkative friend who asks about life experiences (countries visited, food tried, unusual jobs, sports). Ask 'Have you ever...?' questions and ask for details when the learner says yes. Also share your own experiences briefly.","open":"Let's talk about experiences. Have you ever travelled abroad?","targets":["Have you ever","I've never","I've already","for / since"],"goal":"Trò chuyện về những trải nghiệm bạn từng có."}}]},{"id":"s5","n":"Chặng 5","t":"Nói trôi chảy","lv":"B2","goal":"Nói dài, có cấu trúc, thảo luận chủ đề xã hội và xử lý tình huống phức tạp.","lessons":[{"id":"s5l1","t":"Nói liền mạch & từ đệm","vi":"Fluency and fillers","goal":"Giữ nhịp nói, câu giờ tự nhiên khi nghĩ.","ph":[["Well, let me think about that for a moment.","À, để tôi nghĩ về điều đó một chút."],["That's an interesting question.","Đó là một câu hỏi thú vị."],["What I mean is that it depends.","Ý tôi là còn tùy."],["To put it another way, it's too risky.","Nói cách khác, nó quá rủi ro."],["How can I put this?","Tôi nên nói thế nào nhỉ?"],["Anyway, getting back to the point...","Dù sao, quay lại vấn đề chính..."]],"dl":[["A","Why did you choose to study abroad?","Sao bạn chọn đi du học?"],["B","Well, that's a good question. Basically, I wanted a new challenge.","À, câu hỏi hay. Về cơ bản tôi muốn một thử thách mới."],["A","Was it difficult?","Có khó không?"],["B","To be honest, yes. What I mean is that everything was new.","Thật lòng thì có. Ý tôi là mọi thứ đều mới."]],"tip":"Người nói trôi chảy không phải người không ngừng, mà là người ngừng một cách tự nhiên. Dùng \"well\", \"let me see\", \"to be honest\" thay cho \"ờ..., ừm...\" kéo dài. Sửa câu giữa chừng bằng \"what I mean is...\" thay vì dừng hẳn.","ai":{"role":"An interviewer on a podcast who asks open questions that need a few sentences to answer. Ask about the learner's decisions and experiences; let them think and use natural fillers. Do not interrupt; ask a follow-up only after a full answer.","open":"Welcome to the show! Let's start with a simple question: what's the biggest decision you've made in the last year?","targets":["Well","To be honest","What I mean is","Let me think"],"goal":"Trả lời câu hỏi mở bằng 4–5 câu liền mạch."}},{"id":"s5l2","t":"Thảo luận chủ đề xã hội","vi":"Discussing social issues","goal":"Phân tích hai mặt của một vấn đề.","ph":[["There are several advantages and disadvantages.","Có nhiều ưu điểm và nhược điểm."],["On the one hand, it saves time.","Một mặt, nó tiết kiệm thời gian."],["On the other hand, it can be costly.","Mặt khác, nó có thể tốn kém."],["It has both positive and negative effects.","Nó có cả tác động tích cực lẫn tiêu cực."],["Overall, I'd say the benefits outweigh the risks.","Nhìn chung, tôi cho rằng lợi ích lớn hơn rủi ro."],["It's a complex issue with no easy answer.","Đó là vấn đề phức tạp, không có đáp án dễ."]],"dl":[["A","Is social media good or bad for young people?","Mạng xã hội tốt hay xấu cho người trẻ?"],["B","On the one hand, it helps them stay connected.","Một mặt, nó giúp họ giữ kết nối."],["A","And on the other hand?","Còn mặt kia?"],["B","It can affect their sleep. Overall, it depends on how they use it.","Nó có thể ảnh hưởng giấc ngủ. Nhìn chung, tùy cách họ dùng."]],"tip":"Khung cân bằng: một mặt → mặt khác → kết luận của bạn. Thêm ví dụ thật cho mỗi mặt. Kết luận bằng \"Overall, ...\" hoặc \"All things considered, ...\".","ai":{"role":"A thoughtful radio host discussing a social topic (social media, remote work, tourism, AI in schools). Ask the learner to weigh both sides and give a conclusion. Challenge them once with a counter-argument and ask for an example.","open":"Today's topic is artificial intelligence in schools. Is it a good idea?","targets":["On the one hand","On the other hand","Overall","For instance"],"goal":"Thảo luận hai mặt của một vấn đề xã hội."}},{"id":"s5l3","t":"Giả định & điều kiện","vi":"Hypotheticals","goal":"Nói điều giả định bằng câu điều kiện loại 2 và 3.","ph":[["If I had more time, I would learn Spanish.","Nếu có thêm thời gian, tôi sẽ học tiếng Tây Ban Nha."],["If I were you, I'd accept the offer.","Nếu tôi là bạn, tôi sẽ nhận lời."],["What would you do if you won the lottery?","Bạn sẽ làm gì nếu trúng xổ số?"],["If I had known, I would have called you.","Nếu biết trước, tôi đã gọi cho bạn."],["I wish I had studied harder.","Giá mà tôi đã học chăm hơn."],["Unless it rains, we'll go.","Trừ khi trời mưa, chúng tôi sẽ đi."]],"dl":[["A","What would you do if you could live anywhere?","Bạn sẽ làm gì nếu sống ở đâu cũng được?"],["B","If I could live anywhere, I'd choose Japan.","Nếu sống ở đâu cũng được, tôi chọn Nhật."],["A","Why Japan?","Sao lại Nhật?"],["B","If I lived there, I could learn the language and culture.","Nếu sống ở đó, tôi có thể học ngôn ngữ và văn hóa."]],"tip":"Loại 2: If + quá khứ đơn, would + V (điều không có thật ở hiện tại). Với \"be\" nói \"If I were\". Loại 3: If + had + V3, would have + V3 (điều đã không xảy ra). \"Wish\" + quá khứ để nói tiếc nuối hiện tại.","ai":{"role":"A curious friend who loves hypothetical questions ('What would you do if...?'). Ask 3 different scenarios (money, time, job, past regret) and follow up on the learner's reasons. Encourage conditionals.","open":"Let's play 'What if?'. What would you do if you suddenly had a free year?","targets":["If I had","I would","If I were","I wish"],"goal":"Trả lời các câu 'What would you do if...?'."}},{"id":"s5l4","t":"Thuyết trình ngắn","vi":"A short presentation","goal":"Mở bài, triển khai, kết bài cho bài nói 2 phút.","ph":[["Today I'd like to talk about remote work.","Hôm nay tôi muốn nói về làm việc từ xa."],["I'll start by explaining why it matters.","Tôi sẽ bắt đầu bằng việc giải thích vì sao nó quan trọng."],["Let me give you an example.","Để tôi đưa ra một ví dụ."],["This brings me to my next point.","Điều này đưa tôi đến ý tiếp theo."],["To sum up, remote work is here to stay.","Tóm lại, làm việc từ xa sẽ còn ở lại."],["Thank you for listening. Any questions?","Cảm ơn đã lắng nghe. Có câu hỏi nào không?"]],"dl":[["A","Could you give us a short talk on your topic?","Bạn có thể nói ngắn về chủ đề của bạn không?"],["B","Sure. Today I'd like to talk about healthy habits.","Được. Hôm nay tôi muốn nói về thói quen lành mạnh."],["A","Go ahead.","Mời bạn."],["B","First, sleep. Second, exercise. To sum up, small habits make a big difference.","Thứ nhất là ngủ. Thứ hai là vận động. Tóm lại, thói quen nhỏ tạo khác biệt lớn."]],"tip":"Cấu trúc 3 phần: Mở (nêu chủ đề + vì sao quan trọng) → Thân (2–3 ý, mỗi ý có ví dụ) → Kết (tóm tắt + câu cuối). Dùng từ chuyển ý để người nghe không lạc.","ai":{"role":"A workshop host who asks the learner to give a 1–2 minute talk on a topic they choose (a hobby, a habit, a city). After the talk, ask two audience questions. Let the learner open, develop with examples, and sum up.","open":"Welcome to our speaking workshop! Please pick any topic you like and tell us about it for a minute or two.","targets":["Today I'd like to talk about","First","For example","To sum up"],"goal":"Thuyết trình một chủ đề bạn chọn trong 1–2 phút."}},{"id":"s5l5","t":"Đàm phán & thương lượng","vi":"Negotiating","goal":"Đưa đề nghị, nhượng bộ, chốt thỏa thuận.","ph":[["Would you be willing to lower the price?","Bạn có sẵn lòng giảm giá không?"],["I could offer you a ten percent discount.","Tôi có thể giảm cho bạn mười phần trăm."],["If you order more, I'll include delivery.","Nếu bạn đặt thêm, tôi sẽ miễn phí giao hàng."],["Let's meet halfway.","Hãy cùng nhượng bộ một nửa."],["That's the best I can do.","Đó là mức tốt nhất tôi làm được."],["We have a deal.","Chúng ta chốt thỏa thuận."]],"dl":[["A","The rent is eight hundred a month.","Tiền thuê là tám trăm một tháng."],["B","Would you be willing to accept seven fifty?","Bạn có chấp nhận bảy trăm năm mươi không?"],["A","I could do seven eighty if you sign for a year.","Tôi giảm còn 780 nếu bạn ký một năm."],["B","That sounds fair. We have a deal.","Nghe hợp lý. Chốt nhé."]],"tip":"Đàm phán cần mềm về lời, rõ về nội dung: nêu mong muốn, đề nghị điều kiện, nhượng bộ có đi có lại. Dùng \"would you be willing to...\" thay cho yêu cầu thẳng.","ai":{"role":"A landlord negotiating the rent and conditions of a flat with the learner (price, deposit, contract length, repairs). Start high, make counter-offers and finally agree if the learner negotiates politely and reasonably.","open":"The flat is available, and the rent is nine hundred a month. What do you think?","targets":["Would you be willing","I could offer","Let's meet halfway","We have a deal"],"goal":"Thương lượng giá thuê nhà."}},{"id":"s5l6","t":"Họp & trình bày giải pháp","vi":"Meetings and solutions","goal":"Đề xuất, ngắt lời, làm rõ và chốt hành động.","ph":[["Can I just add something here?","Cho tôi bổ sung một điều ở đây được không?"],["I'd suggest we postpone the launch.","Tôi đề xuất hoãn buổi ra mắt."],["Could you clarify what you mean by that?","Bạn làm rõ ý đó giúp tôi được không?"],["Let's go through the action points.","Hãy xem lại các việc cần làm."],["I'll send you the report by Friday.","Tôi sẽ gửi báo cáo cho bạn trước thứ Sáu."],["Shall we move on to the next item?","Chúng ta sang mục tiếp theo nhé?"]],"dl":[["A","We're behind schedule. Any suggestions?","Chúng ta đang trễ tiến độ. Có đề xuất nào không?"],["B","I'd suggest we add one more person to the team.","Tôi đề xuất thêm một người vào nhóm."],["A","Could you clarify the budget for that?","Bạn làm rõ ngân sách cho việc đó chứ?"],["B","Of course. I'll send the details by tomorrow.","Tất nhiên. Mai tôi sẽ gửi chi tiết."]],"tip":"Họp bằng tiếng Anh cần 3 kỹ năng: chen vào lịch sự (Can I add something?), làm rõ (Could you clarify...?), chốt hành động (I'll... by...). Câu ngắn, rõ, có chủ ngữ và hạn chót.","ai":{"role":"A project manager chairing a team meeting where a project is late. Ask the learner for causes and solutions, interrupt once politely to ask for clarification, and finally assign action points with deadlines.","open":"Let's get started. As you know, we're two weeks behind. What went wrong, in your view?","targets":["I'd suggest","Could you clarify","I'll ... by","Shall we"],"goal":"Họp nhóm: đề xuất giải pháp và chốt việc."}},{"id":"s5l7","t":"Xử lý hiểu lầm & nói tế nhị","vi":"Handling misunderstandings","goal":"Từ chối, góp ý và xin lỗi một cách khéo léo.","ph":[["I'm afraid I can't do that.","Tôi e là tôi không làm được."],["I'd rather not, if you don't mind.","Nếu bạn không phiền, tôi xin không."],["With all due respect, I see it differently.","Với tất cả sự tôn trọng, tôi nhìn khác."],["Perhaps I wasn't clear. What I meant was...","Có lẽ tôi chưa rõ. Ý tôi là..."],["I apologise for the confusion.","Tôi xin lỗi vì sự nhầm lẫn."],["Can we find a way forward?","Chúng ta tìm hướng giải quyết nhé?"]],"dl":[["A","You said the report would be ready yesterday.","Bạn đã nói báo cáo sẽ xong hôm qua."],["B","I apologise for the confusion. I thought you meant Friday.","Tôi xin lỗi vì nhầm lẫn. Tôi tưởng bạn nói thứ Sáu."],["A","I see. Can you finish it today?","Hiểu rồi. Hôm nay bạn xong được không?"],["B","Yes, I'll send it by five.","Được, tôi sẽ gửi trước 5 giờ."]],"tip":"Nói tế nhị = làm mềm câu nói: I'm afraid, with all due respect, perhaps, a bit. Khi bị hiểu nhầm, nhận phần mình (I wasn't clear) rồi đề xuất bước tiếp theo.","ai":{"role":"A colleague who is upset because of a misunderstanding (a missed deadline, a wrong email). Express frustration politely. The learner must apologise, clarify and propose a solution diplomatically. Calm down if they handle it well.","open":"Hi, I wanted to talk about the email you sent. There seems to be a misunderstanding...","targets":["I apologise","What I meant was","I'm afraid","Can we find a way"],"goal":"Gỡ một hiểu lầm công việc một cách khéo léo."}}]},{"id":"s6","n":"Chặng 6","t":"Diễn đạt mọi thứ","lv":"C1","goal":"Nói tự nhiên, chính xác, có sắc thái; xử lý chủ đề trừu tượng và tranh luận.","lessons":[{"id":"s6l1","t":"Diễn đạt trừu tượng","vi":"Abstract ideas","goal":"Nói về giá trị, xu hướng, nguyên nhân sâu xa.","ph":[["There's a growing trend towards remote work.","Có một xu hướng ngày càng tăng về làm việc từ xa."],["A key factor is the cost of living.","Một yếu tố then chốt là chi phí sinh hoạt."],["It raises important questions about privacy.","Nó đặt ra những câu hỏi quan trọng về quyền riêng tư."],["This can be attributed to several causes.","Điều này có thể do nhiều nguyên nhân."],["In the long run, it may change our values.","Về lâu dài, nó có thể thay đổi giá trị của chúng ta."],["The underlying issue is inequality.","Vấn đề cốt lõi là bất bình đẳng."]],"dl":[["A","Why are so many young people delaying marriage?","Vì sao nhiều người trẻ trì hoãn kết hôn?"],["B","A key factor is the cost of housing.","Một yếu tố then chốt là chi phí nhà ở."],["A","Is that the only reason?","Đó là lý do duy nhất sao?"],["B","No. The underlying issue is also a shift in values.","Không. Vấn đề cốt lõi còn là sự thay đổi giá trị."]],"tip":"Chuyển từ \"I think X\" sang cấu trúc trừu tượng: \"A key factor is...\", \"This can be attributed to...\", \"It raises questions about...\". Dùng danh từ hóa để câu nghe học thuật và cô đọng hơn.","ai":{"role":"A sociologist interviewing the learner about trends in society (urbanisation, ageing, work-life balance, technology). Probe for deeper causes and long-term effects with abstract questions. Ask for 'why' twice and challenge superficial answers once.","open":"I'd like your view on a broader social trend: people are moving from villages into cities. What's driving that?","targets":["A key factor","can be attributed to","In the long run","The underlying issue"],"goal":"Phân tích nguyên nhân và hệ quả của một xu hướng xã hội."}},{"id":"s6l2","t":"Lập luận & phản biện","vi":"Arguing and rebuttal","goal":"Xây dựng lập luận chặt, phản bác có dẫn chứng.","ph":[["My central argument is that education should be free.","Luận điểm chính của tôi là giáo dục nên miễn phí."],["The evidence suggests otherwise.","Bằng chứng cho thấy điều ngược lại."],["That may be true, yet it overlooks one thing.","Điều đó có thể đúng, nhưng nó bỏ sót một điều."],["Let me challenge that assumption.","Để tôi thách thức giả định đó."],["Even if that were the case, it wouldn't justify it.","Dù đúng vậy, nó cũng không biện minh được."],["I concede the point, but my position stands.","Tôi thừa nhận điểm đó nhưng lập trường vẫn giữ."]],"dl":[["A","Public transport should be free for everyone.","Giao thông công cộng nên miễn phí cho tất cả."],["B","That may be true in theory, yet it overlooks the cost.","Về lý thuyết có thể đúng, nhưng nó bỏ qua chi phí."],["A","The long-term savings would outweigh the cost.","Tiết kiệm dài hạn sẽ lớn hơn chi phí."],["B","I concede the point, but funding it remains a challenge.","Tôi thừa nhận, nhưng nguồn kinh phí vẫn là thách thức."]],"tip":"Phản biện tốt gồm: tóm lại ý đối phương → chỉ ra điểm yếu → đưa bằng chứng/ví dụ → khẳng định lại lập trường. Tránh tấn công cá nhân; tập trung vào lập luận.","ai":{"role":"A formal debate opponent. Take a clear position on a topic (school uniforms, a four-day week, free transport) and defend it. The learner must rebut with evidence. Concede points that are strong, push back on weak ones, and keep the tone respectful.","open":"Let's debate. I believe a four-day working week should become the standard. Convince me otherwise.","targets":["That may be true, yet","The evidence suggests","I concede","My position is"],"goal":"Tranh luận với một đối thủ lập luận chặt chẽ."}},{"id":"s6l3","t":"Thành ngữ & cụm cố định","vi":"Idioms and collocations","goal":"Dùng cụm tự nhiên thay cho câu dịch từng chữ.","ph":[["It's a piece of cake.","Dễ như ăn bánh."],["I'm snowed under with work.","Tôi ngập đầu trong công việc."],["Let's call it a day.","Hôm nay đến đây thôi."],["It rings a bell.","Nghe quen quen."],["We're on the same page.","Chúng ta cùng quan điểm."],["That's easier said than done.","Nói dễ hơn làm."]],"dl":[["A","How did the exam go?","Bài thi thế nào?"],["B","It was a piece of cake. I'm over the moon!","Dễ ợt. Tôi vui phát điên!"],["A","Great! Shall we celebrate?","Tuyệt! Ăn mừng nhé?"],["B","Let's call it a day and go out for dinner.","Thôi hôm nay xong rồi, đi ăn tối nhé."]],"tip":"Đừng nhồi thành ngữ; dùng 1–2 cái đúng chỗ thì tự nhiên hơn nhiều. Collocation (make a decision, take a break, heavy rain) quan trọng hơn thành ngữ: học theo cụm, không theo từng từ.","ai":{"role":"A chatty friend who enjoys informal language and idioms. Chat about work, weekends and plans using natural idioms, and invite the learner to use some themselves. If they use a phrase unnaturally, suggest the idiomatic alternative.","open":"Hey! How's your week going? You look like you've been busy.","targets":["piece of cake","snowed under","call it a day","on the same page"],"goal":"Trò chuyện thân mật với vài thành ngữ tự nhiên."}},{"id":"s6l4","t":"Kể chuyện hấp dẫn","vi":"Storytelling with impact","goal":"Dẫn dắt, tạo kịch tính, rút ra bài học.","ph":[["You won't believe what happened.","Bạn sẽ không tin chuyện gì xảy ra đâu."],["Out of nowhere, the lights went out.","Bỗng dưng đèn tắt hết."],["To make matters worse, it started pouring.","Tệ hơn nữa, trời bắt đầu mưa như trút."],["Looking back, it taught me a lot.","Nhìn lại, nó dạy tôi nhiều điều."],["The moral of the story is to stay calm.","Bài học của câu chuyện là hãy giữ bình tĩnh."],["Long story short, we made it.","Nói ngắn gọn, chúng tôi đã đến nơi."]],"dl":[["A","Tell me about the worst trip you've had.","Kể về chuyến đi tệ nhất của bạn."],["B","You won't believe it. Our bus broke down in the middle of nowhere.","Bạn sẽ không tin đâu. Xe buýt hỏng giữa chỗ hoang vắng."],["A","Oh no. And then?","Ôi. Rồi sao?"],["B","To make matters worse, it started pouring. Long story short, a farmer saved us.","Tệ hơn nữa là trời mưa to. Nói ngắn gọn, một bác nông dân đã cứu chúng tôi."]],"tip":"Câu chuyện hay có: bối cảnh → vấn đề → leo thang → giải quyết → bài học. Dùng đa dạng thì (past simple, past continuous, past perfect) và cụm dẫn dắt để giữ người nghe.","ai":{"role":"A podcast host who loves storytelling. Ask the learner to tell a memorable story (a funny failure, a lucky escape, a life-changing moment) and ask follow-ups about feelings and what they learnt. Encourage dramatic phrases and varied tenses.","open":"Welcome! I'd love to hear your best story. Think of a moment that really stuck with you...","targets":["Out of nowhere","To make matters worse","Looking back","Long story short"],"goal":"Kể một câu chuyện đáng nhớ với kịch tính và bài học."}},{"id":"s6l5","t":"Nói về công việc & sự nghiệp","vi":"Career talk","goal":"Nói chuyên nghiệp về mục tiêu, thành tựu, thách thức.","ph":[["I'm responsible for managing a team of five.","Tôi chịu trách nhiệm quản lý một nhóm năm người."],["One of my proudest achievements was launching a product.","Một thành tựu tự hào của tôi là ra mắt một sản phẩm."],["I'm looking to take on more responsibility.","Tôi muốn nhận thêm trách nhiệm."],["I thrive under pressure.","Tôi làm việc tốt dưới áp lực."],["My long-term goal is to move into leadership.","Mục tiêu dài hạn của tôi là lên vị trí lãnh đạo."],["I learnt a great deal from that setback.","Tôi học được rất nhiều từ thất bại đó."]],"dl":[["A","What would you say is your greatest achievement?","Theo bạn thành tựu lớn nhất là gì?"],["B","Leading a team that increased sales by thirty percent.","Dẫn dắt nhóm tăng doanh số 30%."],["A","And a challenge you've overcome?","Và một thử thách bạn đã vượt qua?"],["B","A tight deadline. I learnt a great deal about prioritising.","Một hạn chót gấp. Tôi học được nhiều về việc ưu tiên."]],"tip":"Dùng STAR: Situation (bối cảnh) – Task (nhiệm vụ) – Action (hành động) – Result (kết quả, có số liệu). Dùng động từ mạnh: led, launched, improved, negotiated.","ai":{"role":"A senior recruiter conducting a final-round interview. Ask behavioural questions ('Tell me about a time when...'), probe weak answers, and ask about career goals. Let the learner use the STAR method.","open":"Thanks for coming back. Tell me about a time when you had to deal with a very difficult situation at work.","targets":["I was responsible for","I achieved","I learnt","My long-term goal"],"goal":"Phỏng vấn vòng cuối với câu hỏi theo tình huống."}},{"id":"s6l6","t":"Nói tinh tế: thuyết phục & đồng cảm","vi":"Persuasion and empathy","goal":"Thuyết phục nhẹ nhàng, an ủi và khuyên người khác.","ph":[["I completely understand how you feel.","Tôi hoàn toàn hiểu cảm giác của bạn."],["Have you considered another approach?","Bạn đã nghĩ đến cách tiếp cận khác chưa?"],["It might be worth giving it a try.","Có lẽ đáng để thử."],["I can see both sides of the argument.","Tôi thấy được cả hai phía của vấn đề."],["If it were me, I'd take some time off.","Nếu là tôi, tôi sẽ nghỉ một thời gian."],["Whatever you decide, I'll support you.","Dù bạn quyết định gì, tôi sẽ ủng hộ."]],"dl":[["A","I'm thinking of quitting my job.","Mình đang nghĩ đến chuyện nghỉ việc."],["B","I understand how you feel. Have you considered talking to your manager first?","Mình hiểu cảm giác của bạn. Bạn đã thử nói với quản lý trước chưa?"],["A","Not really. I don't think it would help.","Chưa. Mình không nghĩ nó giúp được."],["B","It might be worth a try. Whatever you decide, I'll support you.","Có thể đáng thử. Dù bạn quyết định thế nào, mình ủng hộ."]],"tip":"Thuyết phục tốt bắt đầu bằng thấu hiểu rồi mới đưa gợi ý, và dùng ngôn ngữ mềm (might, perhaps, have you considered). Tránh ra lệnh; để người nghe tự thấy giải pháp.","ai":{"role":"A close friend who is stressed and torn about a big decision (moving abroad, quitting a job, changing major). Share your worries and let the learner respond with empathy and gentle persuasion. React realistically to their advice.","open":"Can I talk to you about something? I've been feeling really stuck lately...","targets":["I understand","Have you considered","It might be worth","Whatever you decide"],"goal":"Đồng cảm và khuyên nhủ một người bạn đang bế tắc."}},{"id":"s6l7","t":"Thảo luận chủ đề tự do","vi":"Free discussion","goal":"Duy trì cuộc trò chuyện dài, đổi chủ đề, kể và hỏi lại.","ph":[["That reminds me of something.","Điều đó làm tôi nhớ ra chuyện này."],["Speaking of which, have you heard about...?","Nhắc mới nhớ, bạn đã nghe về... chưa?"],["Can I ask what you think about it?","Cho mình hỏi bạn nghĩ gì về điều đó?"],["I hadn't thought of it that way.","Mình chưa nghĩ theo cách đó."],["That's a fair point.","Đó là ý hợp lý."],["Going back to what you said earlier...","Quay lại điều bạn nói lúc nãy..."]],"dl":[["A","I've been reading about space tourism lately.","Dạo này tôi đọc về du lịch vũ trụ."],["B","Speaking of which, would you go if you had the money?","Nhắc mới nhớ, bạn có đi nếu có tiền không?"],["A","Probably not. It's too risky.","Có lẽ không. Rủi ro quá."],["B","That's a fair point. I hadn't thought of the risks.","Ý hợp lý. Tôi chưa nghĩ đến rủi ro."]],"tip":"Để hội thoại sống, bạn phải biết: chuyển chủ đề tự nhiên, đào sâu bằng câu hỏi mở, phản hồi bằng cảm nhận (\"That's fascinating\"). Đây là bài tổng kết — hãy nói tự do và bỏ qua nỗi sợ sai.","ai":{"role":"A curious, well-read friend who can talk about any subject (technology, travel, food, culture, ethics). Start with one topic, develop it, then change topic naturally two or three times. Ask open questions and respond with your own opinions. Keep it conversational.","open":"Hey! It's so good to catch up. What's been on your mind lately?","targets":["That reminds me","Speaking of which","I hadn't thought","That's a fair point"],"goal":"Trò chuyện tự do 5–7 phút về mọi chủ đề."}}]}];